133. pub const fn align_up(value: usize, alignment: usize) -> Option<usize> {
134.     if alignment == 0 {
135.         return None;
136.     }
137.     // VERUS DEVIATION: the original body was
138.     //   `value.div_ceil(alignment).checked_mul(alignment)`.
139.     // Verus ships no specification for the `usize::div_ceil` intrinsic (confirmed:
140.     // not present in vstd `std_specs`), and the only ways to give it meaning are
141.     // `assume_specification`/`external_body`, both of which are unapproved cheating
142.     // for this function. The ceiling division is therefore open-coded into the
143.     // arithmetically-equivalent `value / alignment` (+1 on a non-zero remainder).
144.     // This preserves semantics and O(1) time/space. `qd + 1` cannot overflow
145.     // because a non-zero remainder forces `alignment >= 2`, hence
146.     // `qd <= value / 2 < usize::MAX` (see `lemma_ceil_div`).
147.     let r: usize = value % alignment;
148.     let qd: usize = value / alignment;
149.     proof! {
150.         vstd::arithmetic::div_mod::lemma_fundamental_div_mod(value as int, alignment as int);
151.         if r != 0 {
152.             assert(alignment >= 2);
153.             assert((alignment as int) * (qd as int) <= value as int);
154.             assert(2 * (qd as int) <= (alignment as int) * (qd as int)) by (nonlinear_arith)
155.                 requires
156.                     alignment >= 2,
157.                     qd >= 0,
158.             ;
159.             assert(qd < usize::MAX);
160.         }
161.     }
162.     let q: usize = if r == 0 { qd } else { qd + 1 };
163.     proof! {
164.         lemma_ceil_div(value as int, alignment as int, qd as int, r as int);
165.     }

